package dev.jackteng.encore;
import com.fasterxml.jackson.databind.ObjectMapper;
import dev.jackteng.encore.admission.AdmissionSettings;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.StockProjectionService.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.eq;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.stock-maintenance.enabled=true"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockMaintenanceIntegrationTest {
 @Autowired StockProjectionService projections;@org.springframework.test.context.bean.override.mockito.MockitoSpyBean JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;
 @Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired OrderService orders;@Autowired PaymentService payments;@Autowired PurchaseService purchases;@Autowired PlatformTransactionManager transactions;
 @Autowired StockMaintenanceService maintenance;@Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired StockRecoveryStore recovery;@Autowired StockRecoveryWorker recoveryWorker;@Autowired org.springframework.test.web.servlet.MockMvc mvc;
 RedisTicketLedger ledger;final Set<String> ownKeys=new HashSet<>();String manager="maintenance-"+UUID.randomUUID();
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(ownKeys);ownKeys.clear();}
 UUID ticket(){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"maintenance-"+UUID.randomUUID(),"核對演出","合成","合成"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",OffsetDateTime.now().plusDays(2),OffsetDateTime.now().minusHours(1),OffsetDateTime.now().plusHours(2)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);return t.id();}
 CustomerService.Principal customer(){var c=customers.register("pr-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Place place(UUID t){return new Place(UUID.randomUUID(),t,1,1,1200);}
 Rebuild begin(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());ownKeys.add(ledger.key(t,c.generation()));return c;}
 Rebuild ready(UUID t){var c=begin(t);assertEquals("READY",projections.complete(c.requestId()).state());return c;}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 long journal(UUID t){return db.queryForObject("SELECT count(*) FROM stock_revision WHERE ticket_id=?",Long.class,t);}

 StockMaintenanceService.Begin body(UUID request,long revision){return new StockMaintenanceService.Begin(request,revision);}
 StockMaintenanceService.Receipt submit(UUID t){var b=body(UUID.randomUUID(),projections.inspect(t).sourceRevision());ownKeys.add(ledger.key(t,projections.inspect(t).generation()+1));return maintenance.submit(manager,t,b);}
 int audits(UUID request){return db.queryForObject("SELECT count(*) FROM stock_maintenance_audit WHERE request_id=?",Integer.class,request);}
 String other(String role){String name="staff-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),name,"synthetic unused hash",role);return name;}
 @Test void managerRebuildCommitsThreeAuditedCheckpointsWithoutChangingFormalStock(){var t=ticket();var r=submit(t);assertEquals("READY",r.state());assertFalse(r.canResume());assertEquals(1,r.generation());assertEquals(3,r.version());assertEquals(3,audits(r.requestId()));assertEquals(1,journal(t));assertEquals(4,ledger.snapshot(t,1).snapshot().available());assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));}
 @Test void originalReplayIsPgOnlyAndHistoricalReadyDoesNotClaimCurrentGateReady(){var t=ticket();var r=submit(t);redis.delete(ledger.key(t,1));var b=body(r.requestId(),r.expectedSourceRevision());assertEquals(r,maintenance.submit(manager,t,b));orders.place(customer(),place(t));var p=maintenance.progress(manager,r.requestId());assertEquals("READY",p.state());assertEquals("DIRTY",p.currentState());assertEquals(3,audits(r.requestId()));assertEquals(1,p.generation());}
 @Test void sameUuidCannotChangeActorTicketOrRevision(){var t=ticket();var r=submit(t);problem("REQUEST_CONFLICT",()->maintenance.submit(manager,t,body(r.requestId(),2)));problem("REQUEST_CONFLICT",()->maintenance.submit(manager,ticket(),body(r.requestId(),1)));problem("REQUEST_CONFLICT",()->maintenance.submit(other("MANAGER"),t,body(r.requestId(),1)));problem("NOT_FOUND",()->maintenance.progress(other("MANAGER"),r.requestId()));}
 @Test void disabledEntryAllowsOwnedProgressAndTerminalReplayButNoFreshCommand(){var t=ticket();var r=submit(t);var off=new StockMaintenanceService(db,projections,transactions,false);assertEquals(r,off.progress(manager,r.requestId()));assertEquals(r,off.submit(manager,t,body(r.requestId(),1)));problem("MAINTENANCE_DISABLED",()->off.submit(manager,t,body(UUID.randomUUID(),1)));}
 @Test void viewerReadsTicketsAndIssuesButCannotWriteOrAdoptOriginalCommand(){var t=ticket();var r=submit(t);String v=other("VIEWER");assertEquals(t,maintenance.ticket(v,t).ticketId());assertEquals(0,maintenance.issues(v,t,1,12).total());problem("FORBIDDEN",()->maintenance.submit(v,t,body(UUID.randomUUID(),1)));problem("NOT_FOUND",()->maintenance.progress(v,r.requestId()));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertFalse(maintenance.progress(manager,r.requestId()).canResume());problem("FORBIDDEN",()->maintenance.submit(manager,t,body(r.requestId(),1)));}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}}
 @Test void sixConcurrentSameRequestCreateOneEpochAndOneCheckpointHistory()throws Exception{var t=ticket();var request=UUID.randomUUID();ownKeys.add(ledger.key(t,1));try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<StockMaintenanceService.Receipt>>();for(int i=0;i<6;i++)jobs.add(()->maintenance.submit(manager,t,body(request,1)));for(var f:pool.invokeAll(jobs))assertEquals("READY",f.get().state());}assertEquals(3,audits(request));assertEquals(1,projections.inspect(t).generation());}
 @Test void committedPeerAppearingBetweenRegistrationReadsIsReplayed()throws Exception {
  var t=ticket();var request=UUID.randomUUID();ownKeys.add(ledger.key(t,1));
  var paused=new CountDownLatch(1);var peerFinished=new CountDownLatch(1);
  String query="SELECT count(*) FROM stock_rebuild_command WHERE request_id=?";
  doAnswer(invocation->{if(Thread.currentThread().getName().equals("delayed-register")){paused.countDown();assertTrue(peerFinished.await(5,TimeUnit.SECONDS));}return invocation.callRealMethod();})
   .when(db).queryForObject(eq(query),eq(Integer.class),eq(request));
  try(var pool=Executors.newSingleThreadExecutor(job->new Thread(job,"delayed-register"))){
   var delayed=pool.submit(()->maintenance.submit(manager,t,body(request,1)));
   try{assertTrue(paused.await(5,TimeUnit.SECONDS));assertEquals("READY",maintenance.submit(manager,t,body(request,1)).state());}
   finally{peerFinished.countDown();}
   assertEquals("READY",delayed.get().state());
  }finally{doCallRealMethod().when(db).queryForObject(eq(query),eq(Integer.class),eq(request));}
  assertEquals(3,audits(request));assertEquals(1,projections.inspect(t).generation());
 }
 @Test void staleRevisionIsAuditedBlockedWithoutAllocatingGeneration(){var t=ticket();orders.place(customer(),place(t));var r=maintenance.submit(manager,t,body(UUID.randomUUID(),1));assertEquals("BLOCKED",r.state());assertEquals("STOCK_CHANGED",r.failure());assertNull(r.generation());assertEquals(0,projections.inspect(t).generation());assertEquals(2,audits(r.requestId()));}
 @Test void unresolvedHeldAndReviewCannotBeHiddenByNewRebuild(){var t=ticket();ready(t);var who=customer();var h=holds.prepare(who,place(t));holds.apply(h.id());var r=submit(t);assertEquals("BLOCKED",r.state());assertEquals("ACTIVE_STOCK_INTENTS",r.failure());assertEquals(1,projections.inspect(t).generation());assertEquals(1,maintenance.ticket(manager,t).unresolvedIntents());var issue=maintenance.issues(manager,t,1,12).items().getFirst();assertEquals(h.id(),issue.intentId());assertEquals("HELD",issue.state());assertNull(issue.decision());}
 @Test void closedDomainAndAuditRollbackTogether(){var t=ticket();UUID request=UUID.randomUUID();db.execute("ALTER TABLE stock_maintenance_audit ADD CONSTRAINT maintenance_begin_fault CHECK(request_id<>'"+request+"'::uuid OR state<>'CLOSED') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->maintenance.submit(manager,t,body(request,1)));assertEquals(0,projections.inspect(t).generation());assertEquals("REGISTERED",maintenance.progress(manager,request).state());assertEquals(1,audits(request));assertFalse(redis.hasKey(ledger.key(t,1)));}finally{db.execute("ALTER TABLE stock_maintenance_audit DROP CONSTRAINT maintenance_begin_fault");}ownKeys.add(ledger.key(t,1));assertEquals("READY",maintenance.submit(manager,t,body(request,1)).state());}
 @Test void luaOpenBeforeReadyAuditRollbackKeepsClosedAndResumesOriginalEpoch(){var t=ticket();UUID request=UUID.randomUUID();ownKeys.add(ledger.key(t,1));db.execute("ALTER TABLE stock_maintenance_audit ADD CONSTRAINT maintenance_ready_fault CHECK(request_id<>'"+request+"'::uuid OR state<>'READY') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->maintenance.submit(manager,t,body(request,1)));assertEquals("CLOSED",projections.inspect(t).state());assertEquals("CLOSED",maintenance.progress(manager,request).state());assertEquals(RedisTicketLedger.Phase.OPEN,ledger.snapshot(t,1).snapshot().phase());assertEquals(2,audits(request));}finally{db.execute("ALTER TABLE stock_maintenance_audit DROP CONSTRAINT maintenance_ready_fault");}assertEquals("READY",maintenance.submit(manager,t,body(request,1)).state());assertEquals(1,projections.inspect(t).generation());assertEquals(3,audits(request));}
 @Test void roleRevokedBetweenPhasesPreventsRedisOrReadyMutation(){var t=ticket();var request=UUID.randomUUID();db.execute("ALTER TABLE stock_maintenance_audit ADD CONSTRAINT maintenance_role_fault CHECK(request_id<>'"+request+"'::uuid OR state<>'READY') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->maintenance.submit(manager,t,body(request,1)));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);assertFalse(maintenance.progress(manager,request).canResume());problem("FORBIDDEN",()->maintenance.submit(manager,t,body(request,1)));assertEquals("CLOSED",projections.inspect(t).state());assertEquals(2,audits(request));}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);db.execute("ALTER TABLE stock_maintenance_audit DROP CONSTRAINT maintenance_role_fault");ownKeys.add(ledger.key(t,1));}assertEquals("READY",maintenance.submit(manager,t,body(request,1)).state());}
 @Test void corruptLedgerProducesAuditedDirtyAndNeverOpensIt(){var t=ticket();UUID request=UUID.randomUUID();ownKeys.add(ledger.key(t,1));redis.opsForValue().set(ledger.key(t,1),"synthetic-corrupt");var r=maintenance.submit(manager,t,body(request,1));assertEquals("DIRTY",r.state());assertFalse(r.canResume());assertEquals("REDIS_RECONCILIATION_REQUIRED",r.failure());assertEquals("synthetic-corrupt",redis.opsForValue().get(ledger.key(t,1)));assertEquals(3,audits(request));}
 @Test void rebuildingAfterResolvedFormalDecisionUsesNewPgSnapshot(){var t=ticket();ready(t);var who=customer();var h=holds.prepare(who,place(t));holds.apply(h.id());var p=purchases.acceptHold(who,h.id());var event=db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());purchases.process(event);assertEquals("BLOCKED",submit(t).state());assertEquals("COMMITTED",settlement.reconcile(h.id()).resolution());var r=submit(t);assertEquals("READY",r.state());assertEquals(2,r.generation());assertEquals(3,ledger.snapshot(t,2).snapshot().available());assertEquals(1,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,t));}
 @Test void internalLegacyCommandCannotBeAdoptedByStaffOperation(){var t=ticket();var b=begin(t);problem("REQUEST_CONFLICT",()->maintenance.submit(manager,t,body(b.requestId(),1)));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_maintenance_command WHERE request_id=?",Integer.class,b.requestId()));}
 @Test void immutableCommandAndAuditAndReadyProofGuards(){var t=ticket();var r=submit(t);for(String sql:List.of("UPDATE stock_maintenance_command SET source_revision=2 WHERE request_id=?","DELETE FROM stock_maintenance_audit WHERE request_id=?","UPDATE stock_maintenance_progress SET version=version+1 WHERE request_id=?")){var error=assertThrows(org.springframework.dao.DataAccessException.class,()->db.update(sql,r.requestId()));assertInstanceOf(org.postgresql.util.PSQLException.class,error.getMostSpecificCause());assertEquals("P0001",((java.sql.SQLException)error.getMostSpecificCause()).getSQLState());}assertEquals(3,audits(r.requestId()));assertEquals("READY",maintenance.progress(manager,r.requestId()).state());}
 @Test void boundedReadPagesAndMissingOriginalAreSideEffectFree(){problem("INVALID_INPUT",()->maintenance.tickets(manager,1,21));problem("INVALID_INPUT",()->maintenance.issues(manager,ticket(),0,12));problem("NOT_FOUND",()->maintenance.progress(manager,UUID.randomUUID()));problem("NOT_FOUND",()->maintenance.ticket(manager,UUID.randomUUID()));}
 @Test void outerTransactionCannotWrapCoordinator(){var t=ticket();new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->maintenance.submit(manager,t,body(UUID.randomUUID(),1)));return null;});assertEquals(0,projections.inspect(t).generation());}
 @Test void reviewListIsPgOnlyAndNeverResetsBudget(){var t=ticket();ready(t);var h=holds.prepare(customer(),place(t));holds.apply(h.id());redis.delete(ledger.key(t,1));redis.opsForValue().set(ledger.key(t,1),"synthetic-corrupt");holds.abandon(h.id());var c=recovery.claim(30);for(int n=0;c.isPresent()&&!c.get().intentId().equals(h.id())&&n<1000;n++){recoveryWorker.run(c.get());c=recovery.claim(30);}assertTrue(c.isPresent());recovery.failed(c.get(),"REDIS_CORRUPT",true);var issue=maintenance.issues(manager,t,1,12).items().getFirst();assertEquals("REVIEW",issue.unusedJob());assertEquals(1,issue.unusedAttempts());assertEquals(1,maintenance.ticket(manager,t).unresolvedReviews());assertEquals("BLOCKED",submit(t).state());assertEquals(1,maintenance.issues(manager,t,1,12).items().getFirst().unusedAttempts());}
}
